const dossierId = {{ json .dossier_id }};
const preuve = {{ json .preuve }};
const confirmation = {{ json .confirmation_manuelle }};
if (typeof dossierId !== 'string' || !/^[a-z0-9][a-z0-9-]{0,63}$/.test(dossierId)) {
  throw new Error('dossier_id invalide');
}
if (typeof preuve !== 'string' || preuve.trim() === '') {
  return { decision: 'rework', dossier_id: dossierId, reason: 'preuve_obligatoire_manquante' };
}
if (confirmation !== true) {
  return { decision: 'human_review', dossier_id: dossierId, reason: 'validation_humaine_requise' };
}
return { decision: 'accepted', dossier_id: dossierId, reason: 'preuve_et_validation_humaine_presentes' };
